const double EPS = 1e-9;
const int MOD = 1000000007;
int MODM(int a, int b) 
{
    a %= MOD; 
    int ret = 1; 
    while (b) { 
        if (b & 1) ret = (ret * a) % MOD; 
        a = (a * a) % MOD; 
        b >>= 1; 
    } 
    return ret; 
}
signed main() 
{
    ios_base::sync_with_stdio(0); cin.tie(0); 
    vvb M(36,vb(36,0));  
    int a,b,k; cin>>a>>b>>k;

    for(int i=1;i<=k;i++){
        int x,y;
        cin>>x>>y;
        M[x][y]=1;
        M[y][x]=1;
    }
    int n=a; //35
    int s,b,c,i,t; 
    cin>>b>>c>>i>>t;

    vi cfg(36,0);
    vi cfg2(36,0);
    vi difi(2019,0);
    bool reset=false;
    int creturn=0;

    vvi cnt(36,vi(36,0)); //cnt(x,y) is the F's number from y to x
    while(1){
        if(cfg[n]==0){
            int remain=t,i=1;
            for(i=1;i<=n;i++){
                if(cfg[i]>0){
                    remain-=cfg[i]; //花掉
                    cfg[i]=0;
                }
                if(remain<=0) break;
            }
            cfg[i]=t-i;//補上
            difi[t-remain]++;  //儲存一回剩幾路、放幾路
            reset=false;
            creturn=i;
        }
        if(!reset){
            int cnttr=0;
            for(s=1;s<=n;s++){ //依照 cfg 中的 configuration 做
                if(cfg[s]>0){//剩下的位在 s
                    for(b=1;b<=n;b++){//從 b 向 s 去做
                        if(M[s][b]){//把 b 與 s 相連
                            if(cfg[b]>0){//如果 s 准備走的路全都交集到 b, 儲存走法
                                cnttr++;//如果結束的話，所有都在 s 妥協的路都會不成功, 餒了以後「把路交集過的」中在走了的加上來
                                difi[t-cfg[s]-(t-remain)]++;//儲存成功放路的次數以後不能夠對目前 configuration 繼續，除非都結束找不出不成功的路
                                reset=true;
                                break;//中斷,cfg 更新後會繼續之後的
                            }
                        }
                    }
                    if(reset) break; //中斷
                }
            }
            if(reset){
                //輸出
                if(creturn){
                    if(creturn==1){
                        cfg2[1]=1;
                    }else if(creturn==n){
                        cfg2[n]=1;
                    }else{
                        cfg2[creturn]=1;
                        cfg[creturn]=t-cfg[creturn];
                    }
                }else{
                    vi tmp(36); 
                    for(i=1;i<=n;i++){
                        tmp[i]=cfg[i]; 
                    }
                    for(int oo=1;oo<=2019;oo++){ //反方向記錄
                        if(difi[(int)oo]==1 && difi[2019]==difii){
                            for(i=1;i<=n;i++){
                                cfg[i]=tmp[i];
                                if(cfg2[i]==1) difii-=tmp[i];
                            }
                            difii=difi[i]-(int)oo;
                            break;
                        }
                    }
                    //重復
                    if(difi[(int)oo]>1){
                        for(i=1;i<=n;i++){
                            if(cfg2[i]==1){
                                difi[i]=difi[(int)oo];
                                difii=difi[i]-(int)oo;
                                difii++;
                            }
                        }
                    }
                }
                if(creturn){
                    for(i=1;i<=n;i++){
                        if(cfg[i]==0){
                            cfg2[i]=0; 
                        }else{
                            cfg2[creturn]=0;
                            break;
                        }
                    }
                }
            }else{ //remain, 
                int gap=remain;
                if((remain<t)&&(cfg[n]==0)){
                    difi[remain] ++;
                }
            }
        }else{
            break;
        }
    }
    cout<<((int)(difi[0]*2))<<"\n";
    return 0;
}


